// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address k) public {
        vm.assume(k != address(0));
        // Grant auth to caller so that we can call rely/deny if needed, but we won't here.
        c.rely(caller);
        vm.prank(caller);
        uint256 before = c.wards(k);
        c.allowance(address(this), address(this));
        uint256 after = c.wards(k);
        assertTrue(before == after, "wards changed after allowance call");
    }
}

