pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller, address a1, address a2, uint256 amt) public {
        // Ensure that after setup, msg.sender (this contract) is already a ward.
        // We also ensure the caller is a ward.
        c.rely(caller);
        vm.assume(caller != address(0) && c.wards(caller) == 1);
        // Drive a call to allowance via the caller
        vm.prank(caller);
        c.allowance(a1, a2);
        // The rule: after allowance, wards(caller) remains 1
        assertTrue(c.wards(caller) == 1);
    }
}

