pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }
    function testFuzz_property(address caller) public {
        // Ensure caller is not the auth user (msg.sender of setUp)
        vm.assume(caller != address(this));
        // Ensure caller is not the zero address
        vm.assume(caller != address(0));
        // Ensure wards[caller] is 0 initially
        vm.assume(c.wards(caller) == 0);

        // Try calling allowance from caller
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSignature("allowance(address,address)", address(1), address(2)));

        // The rule: if caller is not authorized (wards[caller]==0), the call should revert
        // because the underlying share.allowance call in the original code will not revert, but
        // the buggy version changes the auth modifier to !=0, which would allow the call to proceed.
        // However, the difference stated is that P and M differ on wards[caller] after allowance.
        // But we cannot read internal state directly. We assert a general observable behavior:
        // For any unauthorized caller, the allowance call should revert in the reference (C)
        // because the auth modifier fails. In the buggy version, it passes.
        assertTrue(!success, "Unauthorized caller should revert");
    }
}

