pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(0, bytes16(0), address(this), address(this), address(this)); }

    function testFuzz_property(address caller, address spender) public {
        vm.assume(caller != address(0) && spender != address(0));
        vm.assume(caller != address(c.share())); // avoid share contract calls

        // Record initial authorization status
        bool wasAuthorized = c.wards(caller) == 1;

        // Call allowance
        (bool success, ) = address(c).call(abi.encodeWithSignature("allowance(address,address)", caller, spender));

        if (success) {
            // After a successful allowance call, if caller was not authorized initially
            if (!wasAuthorized) {
                // Then caller should still not be authorized
                vm.prank(caller);
                // Attempt to rely on someone - this should revert if caller is unauthorized
                (bool relySuccess, ) = address(c).call(abi.encodeWithSignature("rely(address)", address(1)));
                assertTrue(!relySuccess, "Unauthorized caller should not be able to rely");
            }
        }
    }
}

