        vm.assume(assets < type(uint256).max / 2);
        // We call totalAssets and compare with convertToShares
        uint256 total = c.totalAssets();
        if (total > 0) {
            // When converting totalAssets to shares using a fixed conversion (assume 1:1 for simplicity),
            // totalShares should be <= totalSupply (since shares represent ownership)
            uint256 sharesFromTotal = c.convertToShares(total);
            // The invariant: convertToShares(totalAssets()) should be less than or equal to totalSupply()
            assertTrue(sharesFromTotal <= c.totalSupply());
        }
    }
}

